@n8n/n8n-nodes-langchain.openAi.expression:
={{((resource, operation) => {
    if (operation === 'deleteAssistant') {
        return 'Delete Assistant';
    }
    if (operation === 'deleteFile') {
        return 'Delete File';
    }
    if (operation === 'classify') {
        return 'Classify Text';
    }
    if (operation === 'message' && resource === 'text') {
        return 'Message Model';
    }
    const capitalize = (str) => {
        const chars = str.split('');
        chars[0] = chars[0].toUpperCase();
        return chars.join('');
    };
    if (['transcribe', 'translate'].includes(operation)) {
        resource = 'recording';
    }
    if (operation === 'list') {
        resource = resource + 's';
    }
    return `${capitalize(operation)} ${capitalize(resource)}`;
})($parameter.resource, $parameter.operation)}}

